const dpdpTa={languageLabel:"மொழி",draftTranslation:"வரைவு மொழிபெயர்ப்பு, இன்னும் சரிபார்க்கப்படவில்லை",noticeFallback:"இந்த அறிவிப்பு உங்கள் மொழியில் இன்னும் கிடைக்கவில்லை, எனவே ஆங்கிலத்தில் காட்டப்படுகிறது.",banner:{title:"உங்கள் தனியுரிமைத் தேர்வுகள்",noOrderImpact:"நீங்கள் எதைத் தேர்ந்தெடுத்தாலும் ஆர்டர் செய்வது அதே போல் செயல்படும்.",acceptAll:"அனைத்தையும் ஏற்கவும்",rejectAll:"அனைத்தையும் நிராகரிக்கவும்",choose:"தேர்வு செய்யவும்",close:'மூடு. இது "அனைத்தையும் நிராகரிக்கவும்" என்பதற்குச் சமம்.'},links:{policy:"தனியுரிமை அறிவிப்பு",rights:"உங்கள் உரிமைகள்",board:"தரவுப் பாதுகாப்பு வாரியத்திடம் புகார் அளிக்கவும்"},prefs:{title:"நாங்கள் எதைப் பயன்படுத்தலாம் என்பதைத் தேர்வு செய்யவும்",intro:'நீங்கள் இயக்கும் வரை விருப்பப் பயன்பாடுகள் முடக்கத்தில் இருக்கும். ஒவ்வொரு பக்கத்தின் கீழும் உள்ள "தனியுரிமைத் தேர்வுகள்" மூலம் எப்போது வேண்டுமானாலும் இதை மாற்றலாம்.',save:"என் தேர்வுகளைச் சேமி",close:"மூடு",necessaryHeading:"சேவையை வழங்க அவசியம்",necessaryExplain:"உங்கள் ஆர்டரைப் பெற, அதற்கான கட்டணத்தைப் பெற மற்றும் டெலிவரி செய்ய, அல்லது சட்டப்படி, எங்களுக்கு இது தேவை. இது ஒப்புதலைச் சார்ந்தது அல்ல, எனவே இதற்கு சுவிட்ச் இல்லை. இருந்தாலும் உங்கள் தரவைத் திருத்த அல்லது அழிக்க நீங்கள் கோரலாம்.",optionalHeading:"விருப்பத்திற்குரியவை",details:"விவரங்கள்",hideDetails:"விவரங்களை மறை",dataUsed:"பயன்படுத்தப்படும் தரவு",enables:"இது எதைச் செயல்படுத்துகிறது",sharedWith:"யாருடன் பகிரப்படுகிறது",outsideIndia:"இந்தியாவுக்கு வெளியே செயலாக்கப்படுகிறது",retention:"எவ்வளவு காலம் வைத்திருப்போம்",switchLabel:"{{purpose}} அனுமதி",childLocked:"18 வயதுக்குட்பட்டவர்களின் கணக்குகளுக்குக் கிடைக்காது.",contact:"உங்கள் தரவு பற்றிய கேள்விகள்: {{name}}, {{email}}",saved:"உங்கள் தேர்வுகள் சேமிக்கப்பட்டன.",unavailable:"தனியுரிமை அறிவிப்பை இப்போது ஏற்ற முடியவில்லை. அதைக் காட்டும் வரை விருப்ப அம்சங்கள் முடக்கத்தில் இருக்கும்.",turnOffEverything:"அனைத்து விருப்பப் பயன்பாடுகளையும் முடக்கு"},collection:{seeNotice:"முழு தனியுரிமை அறிவிப்பைப் படிக்கவும்",registration:{notice:"உங்கள் கணக்கை உருவாக்கிப் பாதுகாக்கவும், உங்கள் ஆர்டர்கள் குறித்து உங்களைத் தொடர்பு கொள்ளவும் உங்கள் பெயர், மின்னஞ்சல் முகவரி, மொபைல் எண் மற்றும் கடவுச்சொல்லைப் பயன்படுத்துகிறோம். இது சேவையை வழங்க அவசியம், எனவே இதற்கு உங்கள் ஒப்புதலைக் கேட்பதில்லை.",ageConfirm:"எனக்கு 18 வயது அல்லது அதற்கு மேல்",ageRequired:'உங்களுக்கு 18 வயது அல்லது அதற்கு மேல் என்பதை உறுதிப்படுத்தவும், அல்லது "எனக்கு 18 வயதுக்குக் குறைவு" என்பதைத் தேர்வு செய்யவும்.',under18:"எனக்கு 18 வயதுக்குக் குறைவு",optionalHeading:"விருப்பத்திற்குரியவை. இவற்றை எப்போது வேண்டுமானாலும் மாற்றலாம்.",marketing:"மின்னஞ்சல், SMS அல்லது புஷ் அறிவிப்பு மூலம் சலுகைகளையும் விளம்பரங்களையும் எனக்கு அனுப்பவும்",recommendations:"என் ஆர்டர் வரலாற்றைக் கொண்டு உணவக மற்றும் உணவுப் பரிந்துரைகளைத் தனிப்பயனாக்கவும்",acknowledge:"தனியுரிமை அறிவிப்பைப் படித்துவிட்டேன்",acknowledgeHelp:"நீங்கள் அறிவிப்பைப் பார்த்தீர்கள் என்பதை மட்டுமே இது உறுதிப்படுத்துகிறது. இது எந்த விருப்பப் பயன்பாட்டுக்கும் ஒப்புதல் அல்ல.",acknowledgeRequired:"தனியுரிமை அறிவிப்பைப் படித்துவிட்டீர்கள் என்பதை உறுதிப்படுத்தவும்."},child:{title:"பெற்றோர் அல்லது பாதுகாவலரின் உதவி தேவை",body:"18 வயதுக்குட்பட்ட ஒருவருக்குக் கணக்கை உருவாக்கவோ அவரது தரவைப் பயன்படுத்தவோ, பெற்றோர் அல்லது சட்டப்பூர்வ பாதுகாவலரின் சரிபார்க்கக்கூடிய ஒப்புதல் சட்டப்படி தேவை. உங்கள் பெற்றோர் அல்லது பாதுகாவலரைத் தங்களைச் சரிபார்க்கச் சொல்லுங்கள்.",startVerification:"பெற்றோர் அல்லது பாதுகாவலரைச் சரிபார்க்கச் சொல்லுங்கள்",pending:"உங்கள் பெற்றோர் அல்லது பாதுகாவலர் சரிபார்க்கக் காத்திருக்கிறோம்.",verified:"உங்கள் பெற்றோர் அல்லது பாதுகாவலர் சரிபார்க்கப்பட்டார். தொடரலாம்.",continue:"தொடரவும்",close:"மூடு",orderBlocked:"இந்தக் கணக்கிலிருந்து ஆர்டர் செய்வதற்கு முன் பெற்றோர் அல்லது பாதுகாவலர் சரிபார்க்க வேண்டும்."},google:{title:"Google மூலம் உள்நுழையவும்",body:"தொடர்ந்தால், Google உங்கள் பெயர், மின்னஞ்சல் முகவரி மற்றும் சுயவிவரப் படத்தை எங்களுடன் பகிரும். உங்கள் கணக்கை உருவாக்கவும் உங்களை உள்நுழைக்கவும் மட்டுமே இவற்றைப் பயன்படுத்துகிறோம். Google LLC இந்த உள்நுழைவை இந்தியாவுக்கு வெளியே செயலாக்குகிறது.",continue:"Google-க்குத் தொடரவும்",cancel:"ரத்துசெய்"},phone:{notice:"உங்களுக்கு ஒருமுறை கடவுச்சொல் அனுப்பவும், உணவகமும் ரைடரும் உங்கள் ஆர்டர் குறித்து உங்களைத் தொடர்பு கொள்ளவும் உங்கள் மொபைல் எண் பயன்படுகிறது. இது சேவையை வழங்க அவசியம்."},login:{notice:"உங்கள் கணக்கைக் கண்டறிந்து உங்களை உள்நுழைக்க உங்கள் மின்னஞ்சல் முகவரியைப் பயன்படுத்துகிறோம்."},checkout:{heading:"இந்த ஆர்டருக்கு உங்கள் விவரங்களை எப்படிப் பயன்படுத்துகிறோம்",delivery:"இந்த ஆர்டரைத் தயாரித்து டெலிவரி செய்ய, உங்கள் பெயர், மொபைல் எண் மற்றும் டெலிவரி முகவரி உணவகத்துடனும் ரைடருடனும் பகிரப்படுகின்றன. இது சேவையை வழங்க அவசியம்.",payment:"ஆன்லைன் கட்டணங்களை Stripe அல்லது PayPal கையாள்கின்றன. உங்கள் கார்டு விவரங்களை அவர்களிடமே உள்ளிடுகிறீர்கள்; உங்கள் கார்டு எண்ணை நாங்கள் பார்ப்பதும் இல்லை, சேமிப்பதும் இல்லை.",marketing:"மின்னஞ்சல், SMS அல்லது புஷ் அறிவிப்பு மூலம் சலுகைகளையும் விளம்பரங்களையும் எனக்கு அனுப்பவும் (விருப்பம்)"},location:{title:"உங்கள் தற்போதைய இருப்பிடத்தைப் பயன்படுத்தவா?",body:"உங்கள் டெலிவரி முகவரியைக் கண்டறிய, இந்தச் சாதனத்தின் துல்லியமான இருப்பிடத்தை உங்கள் உலாவியிடம் ஒருமுறை கேட்போம். விரும்பினால் முகவரியை நீங்களே தட்டச்சு செய்யலாம்.",processor:"Google Maps இருப்பிடத்தை முகவரியாக மாற்றுகிறது. Google இதை இந்தியாவுக்கு வெளியே செயலாக்குகிறது.",allow:"என் இருப்பிடத்தைப் பயன்படுத்து",decline:"முகவரியை நானே தட்டச்சு செய்கிறேன்",declined:"பரவாயில்லை. உங்கள் டெலிவரி முகவரியைத் தட்டச்சு செய்யவும்."},chat:{notice:"இங்கே நீங்கள் அனுப்பும் செய்திகள், இந்த ஆர்டரை டெலிவரி செய்ய உதவுவதற்காக உங்கள் ரைடருடன் பகிரப்பட்டு, உங்கள் ஆர்டருடன் வைக்கப்படுகின்றன."},account:{title:"எங்கள் புதுப்பிக்கப்பட்ட தனியுரிமை அறிவிப்பு",intro:"இந்த அறிவிப்பு வெளியிடப்படுவதற்கு முன்பே உங்கள் கணக்கை உருவாக்கினீர்கள். உங்கள் கணக்கு மற்றும் ஆர்டர்களுக்கு எந்தத் தனிப்பட்ட தரவைப் பயன்படுத்துகிறோம், ஏன், அதை யார் பெறுகிறார்கள், உங்கள் உரிமைகள் என்ன என்பதை இது விளக்குகிறது.",ageQuestion:"உங்கள் வயதை உறுதிப்படுத்தவும்",adult:"எனக்கு 18 வயது அல்லது அதற்கு மேல்",under18:"எனக்கு 18 வயதுக்குக் குறைவு"},notifications:{title:"ஆர்டர் அறிவிப்புகள்",explain:"உங்கள் ஆர்டர் நிலை மாறும்போத